package com.day18.auth.security; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.util.Base64; import org.springframework.stereotype.Service;
@Service public class JwtService { private final String secret=System.getenv().getOrDefault("JWT_SECRET","change-me-in-production-change-me-in-production"); public String create(String sub,String role){long now=Instant.now().getEpochSecond(); String h=b64("{\"alg\":\"HS256\",\"typ\":\"JWT\"}"); String p=b64("{\"sub\":\""+sub+"\",\"role\":\""+role+"\",\"iat\":"+now+",\"exp\":"+(now+3600)+"}"); return h+"."+p+"."+sign(h+"."+p);} private String b64(String s){return Base64.getUrlEncoder().withoutPadding().encodeToString(s.getBytes(StandardCharsets.UTF_8));} private String sign(String x){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(m.doFinal(x.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} }
